    for (const t of traces){ if (t.sheetId !== s.id) continue; const g = t.g; if (g.r1 >= NR || g.c1 >= NC) continue; const x1 = Grid.colLeft[g.c1], y1 = Grid.rowTop[g.r1], x2 = Grid.colLeft[Math.min(g.c2 + 1, NC)], y2 = Grid.rowTop[Math.min(g.r2 + 1, NR)]; out += `<div class="trace${t.dep ? ' dep' : ''}" style="left:${ox + x1}px;top:${oy + y1}px;width:${x2 - x1}px;height:${y2 - y1}px"></div>`; }
