  const SHAPES = [['rect', 'Rectangle'], ['round', 'Rounded rectangle'], ['ellipse', 'Oval'], ['triangle', 'Triangle'], ['arrow', 'Right arrow'], ['larrow', 'Left arrow'], ['star', 'Star'], ['callout', 'Speech bubble'], ['line', 'Line'], ['textbox', 'Text box']];
